1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Scenario {
6	  customer: Customer;
7	  steps: Step[];
8	}
9	
10	export type Step = QuoteStep | ClaimStep;
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Item {
18	  type: string;
19	  material?: string;
20	  enchantment?: number;
21	  cursed?: boolean;
22	}
23	
24	export interface ClaimStep {
25	  op: "claim";
26	  policy: number;
27	  incident: Incident;
28	}
29	
30	export interface Incident {
31	  cause: string;
32	  damages: Damage[];
33	}
34	
35	export interface Damage {
36	  itemType: string;
37	  amount: number;
38	}
39	
40	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
41	
42	export interface ScenarioResult {
43	  results: StepResult[];
44	}
45	
46	const PROCESSING_FEE = 5;
47	
48	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
49	  sword: 100,
50	  staff: 80,
51	  amulet: 60,
52	  potion: 40,
53	  rune: 25,
54	  moonstone: 25,
55	};
56	
57	const FIRST_INSURANCE_PERCENT = 10;
58	
59	// Surcharges are applied as (amount * percent) / 100 rather than via a decimal
60	// multiplier (e.g. * 1.1): the integer intermediate is exact, whereas 100 * 1.1
61	// is 110.00000000000001 in binary floating point. Since the final amount feeds
62	// straight into Math.ceil, that error would round a 115 G premium up to 116 G.
63	const percentOf = (amount: number, percent: number): number =>
64	  (amount * percent) / 100;
65	
66	const itemBasePremium = (item: Item): number => {
67	  const basePremium = BASE_PREMIUM_BY_TYPE[item.type];
68	  if (basePremium === undefined) {
69	    throw new Error(`The MHPCO does not insure items of type "${item.type}"`);
70	  }
71	  return basePremium;
72	};
73	
74	const BLOCK_SIZE = 3;
75	const BLOCK_BASE_PREMIUM = 60;
76	
77	const sumItemBasePremiums = (items: Item[]): number =>
78	  items.reduce((sum, item) => sum + itemBasePremium(item), 0);
79	
80	/** Items of one and the same type, e.g. the three runes that form a block. */
81	type TypeGroup = Item[];
82	
83	const groupByType = (items: Item[]): TypeGroup[] => [
84	  ...items
85	    .reduce(
86	      (groups, item) =>
87	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
88	      new Map<string, TypeGroup>(),
89	    )
90	    .values(),
91	];
92	
93	const formsBlock = (group: TypeGroup): boolean => group.length === BLOCK_SIZE;
94	
95	const groupBasePremium = (group: TypeGroup): number =>
96	  formsBlock(group) ? BLOCK_BASE_PREMIUM : sumItemBasePremiums(group);
97	
98	const policyBasePremium = (items: Item[]): number =>
99	  groupByType(items).reduce((sum, group) => sum + groupBasePremium(group), 0);
100	
101	const CURSE_PERCENT = 50;
102	const HIGH_ENCHANTMENT_PERCENT = 30;
103	const HIGH_ENCHANTMENT_THRESHOLD = 5;
104	
105	/**
106	 * A modifier adjusts a base premium by `percent` when it `applies` to its
107	 * subject. Discounts are expressed as negative percentages, so that the
108	 * applicable rules of one scope always combine by summation.
109	 */
110	interface ModifierRule<Subject> {
111	  applies: (subject: Subject) => boolean;
112	  percent: number;
113	}
114	
115	const applicablePercent = <Subject>(
116	  rules: ModifierRule<Subject>[],
117	  subject: Subject,
118	): number =>
119	  rules.reduce(
120	    (percent, rule) => (rule.applies(subject) ? percent + rule.percent : percent),
121	    0,
122	  );
123	
124	/**
125	 * Item-scoped modifiers apply to the affected item's own base premium, not to
126	 * the policy total.
127	 */
128	const ITEM_MODIFIER_RULES: ModifierRule<Item>[] = [
129	  { applies: (item) => item.cursed === true, percent: CURSE_PERCENT },
130	  {
131	    applies: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
132	    percent: HIGH_ENCHANTMENT_PERCENT,
133	  },
134	];
135	
136	const itemSurcharge = (item: Item): number =>
137	  percentOf(itemBasePremium(item), applicablePercent(ITEM_MODIFIER_RULES, item));
138	
139	const totalItemSurcharges = (items: Item[]): number =>
140	  items.reduce((sum, item) => sum + itemSurcharge(item), 0);
141	
142	const LOYALTY_DISCOUNT_PERCENT = -20;
143	const LOYALTY_THRESHOLD_YEARS = 2;
144	const FOLLOW_UP_DISCOUNT_PERCENT = -15;
145	
146	/**
147	 * Everything a quote needs to know about the scenario around it: whose policy
148	 * this is, and how many quotes preceded it. Not the policy itself — it carries
149	 * no items, insurance sum or cap.
150	 */
151	interface QuoteContext {
152	  customer: Customer;
153	  precedingQuoteCount: number;
154	}
155	
156	/**
157	 * Policy-scoped modifiers apply to the policy base premium (the sum of all
158	 * item base premiums), independently of any item-scoped surcharges.
159	 */
160	const POLICY_MODIFIER_RULES: ModifierRule<QuoteContext>[] = [
161	  { applies: () => true, percent: FIRST_INSURANCE_PERCENT },
162	  {
163	    applies: ({ customer }) =>
164	      customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS,
165	    percent: LOYALTY_DISCOUNT_PERCENT,
166	  },
167	  {
168	    applies: ({ precedingQuoteCount }) => precedingQuoteCount > 0,
169	    percent: FOLLOW_UP_DISCOUNT_PERCENT,
170	  },
171	];
172	
173	const quotePremium = (step: QuoteStep, context: QuoteContext): number => {
174	  const basePremium = policyBasePremium(step.items);
175	  return Math.ceil(
176	    basePremium +
177	      percentOf(basePremium, applicablePercent(POLICY_MODIFIER_RULES, context)) +
178	      totalItemSurcharges(step.items) +
179	      PROCESSING_FEE,
180	  );
181	};
182	
183	const INSURANCE_VALUE_BY_TYPE: Record<string, number> = {
184	  sword: 1000,
185	  staff: 800,
186	  amulet: 600,
187	  potion: 400,
188	  rune: 250,
189	  moonstone: 250,
190	};
191	
192	const DEDUCTIBLE = 100;
193	const CAP_MULTIPLE = 2;
194	
195	const insuranceSum = (items: Item[]): number =>
196	  items.reduce((sum, item) => sum + INSURANCE_VALUE_BY_TYPE[item.type], 0);
197	
198	const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
199	const HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT = 50;
200	
201	/**
202	 * The share of a damage amount the MHPCO reimburses before the deductible.
203	 *
204	 * The spec's dragon-material clause ("fully reimbursed") is not a separate
205	 * branch here: full reimbursement is already the default, and where dragon
206	 * material meets enchantment >= 8 the spec says the 50 % rule wins. Dragon
207	 * material therefore never changes a payout, so encoding it would add a
208	 * branch no input can distinguish.
209	 */
210	const reimbursementPercent = (item: Item): number =>
211	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD
212	    ? HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT
213	    : 100;
214	
215	const damagePayout = (damage: Damage, damagedItem: Item): number =>
216	  percentOf(damage.amount, reimbursementPercent(damagedItem)) - DEDUCTIBLE;
217	
218	/**
219	 * The insured item a damage entry refers to. A damage may name a type the
220	 * policy does not cover at all — the `undefined` case is left for the
221	 * error-handling tests to give meaning.
222	 */
223	const damagedItem = (insuredItems: Item[], damage: Damage): Item | undefined =>
224	  insuredItems.find((item) => item.type === damage.itemType);
225	
226	const totalPayout = (damages: Damage[], insuredItems: Item[]): number =>
227	  Math.floor(
228	    damages.reduce(
229	      (sum, damage) => sum + damagePayout(damage, damagedItem(insuredItems, damage)!),
230	      0,
231	    ),
232	  );
233	
234	/**
235	 * A claim pays what the damages come to, but never more than the policy's
236	 * remaining cap — successive claims against one policy draw down a shared
237	 * budget.
238	 */
239	const cappedPayout = (
240	  damages: Damage[],
241	  insuredItems: Item[],
242	  remainingCap: number,
243	): number => Math.min(totalPayout(damages, insuredItems), remainingCap);
244	
245	/**
246	 * The policy a claim refers to. A `policy` index is only meaningful if it
247	 * points at a quote step, so the lookup narrows rather than casts; the
248	 * `undefined` case is left for the error-handling tests to give meaning.
249	 */
250	const policyAt = (steps: Step[], index: number): QuoteStep | undefined => {
251	  const step = steps[index];
252	  return step?.op === "quote" ? step : undefined;
253	};
254	
255	/**
256	 * What a scenario accumulates as it runs: the remaining cap of every policy
257	 * quoted so far (keyed by the step index a claim names as its `policy`), and
258	 * how many quotes have been issued — the follow-up discount depends on it.
259	 */
260	class Ledger {
261	  private readonly remainingCapByPolicy = new Map<number, number>();
262	  quoteCount = 0;
263	
264	  openPolicy(policyIndex: number, items: Item[]): void {
265	    this.quoteCount++;
266	    this.remainingCapByPolicy.set(policyIndex, CAP_MULTIPLE * insuranceSum(items));
267	  }
268	
269	  /** Draws `payout` down from the policy's cap and reports what is left. */
270	  drawDown(policyIndex: number, payout: number): number {
271	    const remaining = this.remainingCap(policyIndex) - payout;
272	    this.remainingCapByPolicy.set(policyIndex, remaining);
273	    return remaining;
274	  }
275	
276	  remainingCap(policyIndex: number): number {
277	    return this.remainingCapByPolicy.get(policyIndex) ?? 0;
278	  }
279	}
280	
281	export const runScenario = (scenario: Scenario): ScenarioResult => {
282	  const ledger = new Ledger();
283	
284	  const runStep = (step: Step, index: number): StepResult => {
285	    if (step.op === "quote") {
286	      const context = {
287	        customer: scenario.customer,
288	        precedingQuoteCount: ledger.quoteCount,
289	      };
290	      ledger.openPolicy(index, step.items);
291	      return { premium: quotePremium(step, context) };
292	    }
293	
294	    const insuredItems = policyAt(scenario.steps, step.policy)?.items ?? [];
295	    const payout = cappedPayout(
296	      step.incident.damages,
297	      insuredItems,
298	      ledger.remainingCap(step.policy),
299	    );
300	    return { payout, remainingCap: ledger.drawDown(step.policy, payout) };
301	  };
302	
303	  return { results: scenario.steps.map(runStep) };
304	};
